  turf: mat('#315f4c'), stripeA: mat('#386b53'), stripeB: mat('#315f4c'), line: mat('#a8c6a9'),
  dark: mat('#10191b'), stand1: mat('#172628'), stand2: mat('#1b3030'), blue: mat('#16b6d0'), blueDark: mat('#087d9a'),
  red: mat('#e9535d'), redDark: mat('#9e3441'), skin: mat('#e6ad82'), ball: mat('#f4f4e5'), black: mat('#162022'),
