 const characters=[['Yoichi Isagi','Spatial Awareness','FIELD VISION'],['Meguru Bachira','Dribbling','UNPREDICTABLE'],['Seishiro Nagi','Trapping','GENIUS TRAP'],['Rin Itoshi','Curve Shot','PERFECT CONTROL'],['Shoei Barou','Power Shot','KING SHOT'],['Hyoma Chigiri','Speed','44° PANACEA'],['Reo Mikage','Direct Shot','COPY PLAYER'],['Rensuke Kunigami','Power Shot','LEFT CANNON'],['Ryusei Shidou','Predator Eye','GOAL INSTINCT'],['Oliver Aiku','Spatial Awareness','IRON WALL'],['Sae Itoshi','Curve Shot','MAGIC PASS']];
