 $('#modal-root').querySelectorAll('[data-character]').forEach(btn=>btn.onclick=()=>{const c=characters[+btn.dataset.character];career.rivalry++;if(!career.unlocked.includes(c[1])&&career.level>=2)career.unlocked.push(c[1]);saveCareer();toast(`RIVAL DATA: ${c[1].toUpperCase()}`);$('#modal-root').querySelectorAll('.selection-card').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');});
