import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const canvas = $('#game-canvas');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#081214');
scene.fog = new THREE.Fog('#081214', 64, 190);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 260);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.35));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.28;

const mat = (color, roughness = 1, emissive = null) => new THREE.MeshStandardMaterial({ color, roughness, flatShading: true, ...(emissive ? { emissive, emissiveIntensity: .8 } : {}) });
const M = {
 turf:mat('#315f4c'),stripeA:mat('#386b53'),stripeB:mat('#315f4c'),line:mat('#a8c6a9'),dark:mat('#10191b'),stand1:mat('#172628'),stand2:mat('#1b3030'),blue:mat('#16b6d0'),blueDark:mat('#087d9a'),red:mat('#e9535d'),redDark:mat('#9e3441'),skin:mat('#e6ad82'),ball:mat('#f4f4e5'),black:mat('#162022'),lime:mat('#d8ff3e',.55,'#aaff27'),cyan:mat('#00d9df',.45,'#00bbc8'),light:mat('#d8ffed',.3,'#d8ffed')
};
scene.add(new THREE.HemisphereLight('#a9dae0','#183326',2.15));
const keyLight=new THREE.DirectionalLight('#fff1d2',2.2);keyLight.position.set(-32,54,35);scene.add(keyLight);
const rimLight=new THREE.DirectionalLight('#40dfff',1.3);rimLight.position.set(44,30,-42);scene.add(rimLight);
const field=new THREE.Group();scene.add(field);
const pitch=new THREE.Mesh(new THREE.PlaneGeometry(72,112),M.turf);pitch.rotation.x=-Math.PI/2;pitch.position.y=-.12;field.add(pitch);
for(let i=0;i<10;i++){const stripe=new THREE.Mesh(new THREE.PlaneGeometry(72,11.2),i%2?M.stripeA:M.stripeB);stripe.rotation.x=-Math.PI/2;stripe.position.set(0,-.105,-50.4+i*11.2);field.add(stripe)}
function lineLoop(points,color='#b7d4b8',y=.025){const geo=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(p[0],y,p[1])));const obj=new THREE.LineLoop(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.76}));field.add(obj);return obj}
function lineSeg(points,color='#b7d4b8',y=.027){const geo=new THREE.BufferGeometry().setFromPoints(points.map(p=>new THREE.Vector3(p[0],y,p[1])));field.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.72})))}
lineLoop([[-31,-50],[31,-50],[31,50],[-31,50]]);lineSeg([[-31,0],[31,0]]);
lineLoop(Array.from({length:49},(_,i)=>[Math.cos(i*Math.PI*2/48)*9.15,Math.sin(i*Math.PI*2/48)*9.15]));
for(const end of [-1,1]){const z=end*50;lineLoop([[-20,z],[-20,z-end*16.5],[20,z],[20,z-end*16.5]]);lineLoop([[-9.2,z],[-9.2,z-end*5.5],[9.2,z],[9.2,z-end*5.5]]);const mark=new THREE.Mesh(new THREE.CircleGeometry(.17,8),M.line);mark.rotation.x=-Math.PI/2;mark.position.set(0,.028,z-end*11);field.add(mark);const goal=new THREE.Group();goal.position.set(0,0,z+end*1.2);field.add(goal);const postMat=mat('#e5f4ed');for(const x of [-3.8,3.8]){const post=new THREE.Mesh(new THREE.BoxGeometry(.22,3.3,.22),postMat);post.position.set(x,1.65,0);goal.add(post)}const bar=new THREE.Mesh(new THREE.BoxGeometry(7.7,.22,.22),postMat);bar.position.set(0,3.3,0);goal.add(bar);const net=new THREE.Mesh(new THREE.BoxGeometry(7.6,3.15,1.7),new THREE.MeshBasicMaterial({color:'#d9eee8',wireframe:true,transparent:true,opacity:.18}));net.position.set(0,1.58,end*.75);goal.add(net)}
const crowdMats=['#d8ff3e','#efeee3','#08c8d2','#fa5964','#425558','#789a91'].map(c=>mat(c));const stands=new THREE.Group();scene.add(stands);
for(const side of [-1,1])for(let tier=0;tier<4;tier++){const z=side*(61+tier*4.1),h=6.5+tier*2;const wall=new THREE.Mesh(new THREE.BoxGeometry(82,h,3.8),tier%2?M.stand2:M.stand1);wall.position.set(0,h/2-1,z);stands.add(wall);for(let i=0;i<105;i++){const person=new THREE.Mesh(new THREE.BoxGeometry(.48,.62,.48),crowdMats[(Math.random()*crowdMats.length)|0]);person.position.set(-39+Math.random()*78,1+Math.random()*(h-2),z-side*2.15);stands.add(person)}}
for(const x of [-40,40])for(const z of [-55,55]){const pole=new THREE.Mesh(new THREE.BoxGeometry(.5,25,.5),M.dark);pole.position.set(x,12.5,z);scene.add(pole);const lamp=new THREE.Mesh(new THREE.BoxGeometry(7,1,.8),M.light);lamp.position.set(x,25,z);scene.add(lamp)}
let viewMode='menu',cameraYaw=0,cameraZoom=1,cameraShake=0;const camTarget=new THREE.Vector3();
const players=[],teams={blue:[],red:[]};const skinMats=['#f0c49d','#d5a179','#ead0b5','#b97855'].map(c=>mat(c));
function box(parent,size,material,pos){const m=new THREE.Mesh(new THREE.BoxGeometry(...size),material);m.position.set(...pos);parent.add(m);return m}
function makePlayer(team,index,name,weapon,isUser=false,keeper=false){const root=new THREE.Group();scene.add(root);const bodyMat=team==='blue'?M.blue:M.red,shortsMat=team==='blue'?M.blueDark:M.redDark;const torso=box(root,[.92,1.1,.48],bodyMat,[0,1.6,0]);box(root,[.72,.35,.52],shortsMat,[0,.9,0]);const head=box(root,[.48,.55,.48],skinMats[index%skinMats.length],[0,2.48,0]);box(root,[.54,.22,.54],index%3===0?mat('#181a24'):index%3===1?mat('#d6dbe0'):mat('#6a342c'),[0,2.78,-.01]);const armL=new THREE.Group();armL.position.set(-.58,2.04,0);root.add(armL);box(armL,[.25,.78,.28],bodyMat,[0,-.32,0]);const armR=new THREE.Group();armR.position.set(.58,2.04,0);root.add(armR);box(armR,[.25,.78,.28],bodyMat,[0,-.32,0]);const legL=new THREE.Group();legL.position.set(-.25,.83,0);root.add(legL);box(legL,[.32,.82,.38],M.black,[0,-.36,0]);box(legL,[.34,.16,.55],mat('#f3f4e8'),[0,-.78,.08]);const legR=new THREE.Group();legR.position.set(.25,.83,0);root.add(legR);box(legR,[.32,.82,.38],M.black,[0,-.36,0]);box(legR,[.34,.16,.55],mat('#f3f4e8'),[0,-.78,.08]);const number=box(root,[.33,.32,.035],mat('#f1fff2'),[0,1.69,.253]);const player={root,team,index,name,weapon,isUser,keeper,body:torso,head,arms:[armL,armR],legs:[legL,legR],number,velocity:new THREE.Vector3(),target:new THREE.Vector3(),speed:8+Math.random()*1.7,stamina:100,anim:Math.random()*6,skill:Math.random(),flow:false,home:new THREE.Vector3()};root.scale.setScalar(isUser?1.06:keeper?1.05:1);if(isUser)player.speed=9.3;players.push(player);teams[team].push(player);return player}
const roster=[['Yoichi Isagi','Spatial Awareness'],['Meguru Bachira','Dribbling'],['Seishiro Nagi','Trapping'],['Rin Itoshi','Curve Shot'],['Shoei Barou','Power Shot'],['Hyoma Chigiri','Speed'],['Reo Mikage','Direct Shot'],['Rensuke Kunigami','Power Shot'],['Ryusei Shidou','Predator Eye'],['Oliver Aiku','Spatial Awareness'],['Sae Itoshi','Curve Shot']];
const dataDefault={name:'NEW EGOIST',number:9,position:'ST',foot:'RIGHT',hair:'MIDNIGHT',skin:'WARM',eyes:'CYAN',height:178,level:1,xp:0,goals:0,assists:0,rank:'E',rating:32,stats:{speed:44,acceleration:46,finishing:42,accuracy:41,strength:40,control:43,dribble:42,passing:39,vision:42,positioning:43,stamina:70,defense:31},weapon:'Direct Shot',secondaries:['Spatial Awareness'],flowPoints:0,matches:0,rivalry:0,record:0,unlocked:['Direct Shot','Spatial Awareness']};
let career;try{career={...dataDefault,...JSON.parse(localStorage.getItem('egoist-save')||'{}')};career.stats={...dataDefault.stats,...career.stats};career.unlocked=career.unlocked||dataDefault.unlocked;career.secondaries=career.secondaries||dataDefault.secondaries}catch{career={...dataDefault,stats:{...dataDefault.stats}}}
const user=makePlayer('blue',0,career.name,career.weapon,true,false);for(let i=1;i<11;i++)makePlayer('blue',i,roster[i%roster.length][0],roster[i%roster.length][1],false,i===10);for(let i=0;i<11;i++)makePlayer('red',i,['Nagi Type','Iron Wall','Counter Ace','Phantom 9'][i%4],['Direct Shot','Speed','Power Shot','Dribbling'][i%4],false,i===10);
const ballGroup=new THREE.Group();scene.add(ballGroup);const ballMesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.48,1),M.ball);ballGroup.add(ballMesh);for(let i=0;i<3;i++){const patch=new THREE.Mesh(new THREE.IcosahedronGeometry(.18,0),M.black);patch.position.set(Math.cos(i*2.1)*.34,Math.sin(i*2.1)*.28,.25);ballGroup.add(patch)}
const ballShadow=new THREE.Mesh(new THREE.CircleGeometry(.68,12),new THREE.MeshBasicMaterial({color:'#07120d',transparent:true,opacity:.35}));ballShadow.rotation.x=-Math.PI/2;scene.add(ballShadow);const ball={position:new THREE.Vector3(0,.5,0),velocity:new THREE.Vector3(),owner:null,spin:0};
const auraGroup=new THREE.Group();scene.add(auraGroup);const auraRings=[];for(let i=0;i<3;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(1.35+i*.48,.035,4,22),new THREE.MeshBasicMaterial({color:i===1?0x00d9df:0xd8ff3e,transparent:true,opacity:.72}));ring.rotation.x=Math.PI/2;ring.visible=false;auraGroup.add(ring);auraRings.push(ring)}
const formation=[[-22,-19],[-9,-23],[10,-20],[23,-12],[-25,-2],[-12,0],[12,-1],[25,3],[-13,17],[14,18],[0,-46]];for(const p of teams.blue){const f=formation[p.index];p.root.position.set(f[0],0,f[1]);p.root.rotation.y=Math.PI;p.home.set(f[0],0,f[1])}for(const p of teams.red){const f=formation[p.index];p.root.position.set(-f[0],0,-f[1]);p.root.rotation.y=0;p.home.copy(p.root.position)}user.root.position.set(0,0,-8);user.root.rotation.y=Math.PI;user.home.copy(user.root.position);ballGroup.position.copy(ball.position);ballShadow.position.set(0,.01,0);
let match={active:false,paused:false,elapsed:0,duration:120,blue:0,red:0,mode:'career',drill:'finishing',goalFlash:0};
let toastTimer=0,flowTimer=0,flowTier=0,sprintHeld=false,moveInput=new THREE.Vector2(),joyPointer=null,joyOrigin={x:0,y:0};const keys=new Set();let selectedPlayer=user,aiDifficulty=career.difficulty||'STRIKER';
function saveCareer(){try{localStorage.setItem('egoist-save',JSON.stringify(career))}catch(e){console.warn('Career save unavailable',e)}}
function rankFromRating(value){return value>=95?'SSS':value>=86?'SS':value>=76?'S':value>=65?'A':value>=54?'B':value>=44?'C':value>=36?'D':'E'}
function refreshProfile(){user.name=career.name;user.weapon=career.weapon;$('#home-name').textContent=career.name.toUpperCase();$('#home-rank').textContent=career.rank;$('#home-rating').textContent=String(career.rating).padStart(3,'0');$('#home-level').textContent=`LV. ${String(career.level).padStart(2,'0')}`;$('#home-xp').textContent=String(career.xp).padStart(3,'0');$('#home-goals').textContent=String(career.goals).padStart(2,'0');$('#home-meter').style.width=`${Math.max(8,career.rating)}%` $('#field-player-name').textContent=career.name.toUpperCase();$('#field-player-weapon').textContent=career.weapon.toUpperCase();$('#field-player-rank').textContent=career.rank}
refreshProfile();function toast(text){const el=$('#action-toast');el.textContent=text;el.classList.add('show');toastTimer=1.5}
function setMode(mode){$$('.mode-item').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(mode==='career')startCareer();if(mode==='play')startMatch('practice');if(mode==='training')openTraining();if(mode==='roster')openRoster();if(mode==='weapons')openWeapons()}
$$('.mode-item').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));$('#career-start').addEventListener('click',startCareer);$('#profile-edit').addEventListener('click',()=>openCreate(true));$('#settings-open').addEventListener('click',openSettings);
function mountModal(html){$('#modal-root').innerHTML=html;$('#modal-root').querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal)}function closeModal(){$('#modal-root').innerHTML=''}
function openCreate(editing=false){mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">EGOIST PROFILE // PLAYER ID 001</div><h2>${editing?'REDEFINE YOUR EGO':'CREATE YOUR EGO'}</h2><p>Your name will be etched into the facility rankings. The rest is up to your play.</p><div class="form-grid"><div class="form-field"><label>STRIKER NAME</label><input id="create-name" maxlength="16" value="${career.name==='NEW EGOIST'?'':career.name}" placeholder="ENTER NAME"></div><div class="form-field"><label>JERSEY NUMBER</label><input id="create-number" type="number" min="1" max="99" value="${career.number}"></div><div class="form-field"><label>POSITION</label><select id="create-position"><option ${career.position==='ST'?'selected':''}>ST</option><option ${career.position==='LW'?'selected':''}>LW</option><option ${career.position==='RW'?'selected':''}>RW</option><option ${career.position==='CAM'?'selected':''}>CAM</option></select></div><div class="form-field"><label>DOMINANT FOOT</label><select id="create-foot"><option ${career.foot==='RIGHT'?'selected':''}>RIGHT</option><option ${career.foot==='LEFT'?'selected':''}>LEFT</option></select></div><div class="form-field"><label>HAIR</label><select id="create-hair"><option>MIDNIGHT</option><option>SILVER</option><option>CRIMSON</option><option>GOLD</option></select></div><div class="form-field"><label>EYE COLOR</label><select id="create-eyes"><option>CYAN</option><option>AMBER</option><option>VIOLET</option><option>ICE</option></select></div></div><div class="modal-actions"><button class="secondary-button" data-close>CANCEL</button><button class="primary-cta" id="save-player"><span>CONFIRM IDENTITY</span><b>↗</b></button></div></div>`);$('#save-player').onclick=()=>{career.name=$('#create-name').value.trim().toUpperCase()||'EGOIST';career.number=Math.max(1,Math.min(99,+$('#create-number').value||9));career.position=$('#create-position').value;career.foot=$('#create-foot').value;career.hair=$('#create-hair').value;career.eyes=$('#create-eyes').value;saveCareer();refreshProfile();closeModal();if(!editing)showIntro()}}
function startCareer(){if(career.name==='NEW EGOIST'){openCreate(false);return}showIntro()}
function showIntro(){mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">BLUE LOCK FACILITY // INVITATION 001</div><h2>ONE STRIKER.<br>ONE SURVIVOR.</h2><p><strong style="color:#eaf3ed">Ego Jinpachi:</strong> “Japanese football does not need another good team player. It needs one selfish striker who devours every rival. Your first test starts now.”</p><div class="selection-grid"><button class="selection-card selected" data-choice="devour"><b>“I'LL DEVOUR THEM.”</b><small>TAKE THE SHOT. BUILD YOUR EGO.</small></button><button class="selection-card" data-choice="read"><b>“I'LL READ THE FIELD.”</b><small>SEE THE SPACE NO ONE ELSE DOES.</small></button></div><div class="modal-actions"><button class="primary-cta" id="begin-career"><span>BEGIN FIRST SELECTION</span><b>↗</b></button></div></div>`);let selected='devour';$('#modal-root').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{$$('#modal-root [data-choice]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selected=b.dataset.choice});$('#begin-career').onclick=()=>{career.rivalry+=selected==='devour'?2:1;if(selected==='read')career.weapon='Spatial Awareness';saveCareer();refreshProfile();startMatch('career')}}
function openRoster(){const characters=[['Yoichi Isagi','Spatial Awareness','FIELD VISION'],['Meguru Bachira','Dribbling','UNPREDICTABLE'],['Seishiro Nagi','Trapping','GENIUS TRAP'],['Rin Itoshi','Curve Shot','PERFECT CONTROL'],['Shoei Barou','Power Shot','KING SHOT'],['Hyoma Chigiri','Speed','44° PANACEA'],['Reo Mikage','Direct Shot','COPY PLAYER'],['Rensuke Kunigami','Power Shot','LEFT CANNON'],['Ryusei Shidou','Predator Eye','GOAL INSTINCT'],['Oliver Aiku','Spatial Awareness','IRON WALL'],['Sae Itoshi','Curve Shot','MAGIC PASS']];mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">EGOIST ARCHIVE // ELEVEN SELECTED</div><h2>THE STRIKER FILES</h2><p>Study a rival's signature weapon to add it to your training path.</p><div class="selection-grid">${characters.map((c,i)=>`<button class="selection-card" data-character="${i}"><b>${c[0]}</b><small>${c[1].toUpperCase()} · ${c[2]}</small></button>`).join('')}</div><div class="stat-row"><span>RIVALSHIP LEVEL</span><b>${career.rivalry}</b></div></div>`);$('#modal-root').querySelectorAll('[data-character]').forEach(btn=>btn.onclick=()=>{const c=characters[+btn.dataset.character];career.rivalry++;if(!career.unlocked.includes(c[1])&&career.level>=2)career.unlocked.push(c[1]);saveCareer();toast(`RIVAL DATA: ${c[1].toUpperCase()}`);$('#modal-root').querySelectorAll('.selection-card').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected')})}
function openWeapons(){const weapons=[['Direct Shot','Fast first-time finish','STARTER'],['Spatial Awareness','Reveal runs and passing lanes','STARTER'],['Predator Eye','Precision from shooting angles','LV. 2'],['Dribbling','Burst through close pressure','LV. 2'],['Speed','Explosive acceleration','LV. 3'],['Power Shot','High velocity, lower accuracy','LV. 3'],['Curve Shot','Bend shots around defenders','LV. 4'],['Trapping','Magnetic first touch','LV. 4']];mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">WEAPON LOADOUT // 1 PRIMARY + 2 SECONDARY</div><h2>CHOOSE YOUR EDGE</h2><p>Weapons unlock through match growth. Your active primary changes shot, dribble and movement behavior.</p><div class="weapon-list">${weapons.map(([w,d,l])=>{const open=career.unlocked.includes(w)||career.level>=(+l.replace('LV. ','')||1);return `<div class="weapon-row"><div><b>${w}</b><small>${d} · ${open?'UNLOCKED':l+' REQUIRED'}</small></div><button data-equip="${w}" ${open?'':'disabled'}>${career.weapon===w?'EQUIPPED':career.secondaries.includes(w)?'SECONDARY':'EQUIP'}</button></div>`}).join('')}</div></div>`);$('#modal-root').querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const w=b.dataset.equip;if(b.disabled)return;if(career.weapon===w)return;if(career.unlocked.includes(w))career.weapon=w;else if(career.secondaries.includes(w))career.secondaries=career.secondaries.filter(x=>x!==w);else if(career.secondaries.length<2)career.secondaries.push(w);else{career.secondaries.shift();career.secondaries.push(w)}user.weapon=career.weapon;saveCareer();refreshProfile();openWeapons()})}
