function startMatch(mode='career',drill='finishing'){closeModal();match={active:true,paused:false,elapsed:0,duration:mode==='training'?75:120,blue:0,red:0,mode,drill,goalFlash:0};ball.owner=null;ball.velocity.set(0,0,0);ball.position.set(0,.5,0);ballGroup.position.copy(ball.position);user.stamina=100;career.flowPoints=0;flowTimer=0;selectedPlayer=user;for(const p of players){const f=p.home;p.root.position.copy(f);p.velocity.set(0,0,0)}user.root.position.set(0,0,-8);user.home.copy(user.root.position);$('#game-mode-label').textContent=mode==='career'?'CAREER MATCH':mode==='practice'?'QUICK MATCH':mode==='survival'?'SURVIVAL MATCH':`${drill.toUpperCase()} DRILL`;$('#home-screen').classList.add('hidden');$('#game-screen').classList.remove('hidden');$('#touch-controls').classList.add('active');$('#touch-controls').style.pointerEvents='auto';$('#modal-root').innerHTML='';setHud();toast('FIRST TO THE BALL. MAKE YOUR EGO COUNT.')}
function finishMatch(){match.active=false;match.paused=false;ball.owner=null;const won=match.blue>match.red;const earned=20+match.blue*35+(won?30:0)+(match.mode==='training'?12:0);career.xp+=earned;career.matches++;career.record+=won?1:0;career.rating=Math.min(99,career.rating+(won?2:1)+Math.min(match.blue,2));career.rank=rankFromRating(career.rating);career.flowPoints=Math.min(100,career.flowPoints);while(career.xp>=career.level*100){career.xp-=career.level*100;career.level++;career.rating=Math.min(99,career.rating+2);career.unlocked=['Direct Shot','Spatial Awareness',...(career.level>=2?['Predator Eye','Dribbling']:[]),...(career.level>=3?['Speed','Power Shot']:[]),...(career.level>=4?['Curve Shot','Trapping']:[])];}saveCareer();refreshProfile();setHud();mountModal(`<div class="modal result-modal"><div class="modal-kicker">${won?'EGOIST VICTORY':'SELECTION COMPLETE'} // MATCH ${career.matches}</div><h2>${won?'YOU SURVIVED.':'THE PROJECT CONTINUES.'}</h2><p>Final score <strong>${match.blue} — ${match.red}</strong>. You earned <strong>+${earned} XP</strong>${match.mode==='training'?' for your training effort':''}.</p><div class="stat-row"><span>STRIKER RATING</span><b>${career.rating} · ${career.rank}</b></div><div class="stat-row"><span>CAREER RECORD</span><b>${career.record} W / ${career.matches-career.record} L</b></div><div class="modal-actions"><button class="primary-cta" id="result-home"><span>RETURN TO PROJECT</span><b>↗</b></button><button class="secondary-button" id="result-rematch">REMATCH</button></div></div>`);$('#result-home').onclick=()=>{closeModal();$('#game-screen').classList.add('hidden');$('#home-screen').classList.remove('hidden');$('#touch-controls').classList.remove('active')};$('#result-rematch').onclick=()=>startMatch(match.mode,match.drill)}
function resetAfterGoal(team){if(team==='blue'){match.blue++;if(ball.owner===user){career.goals++;career.stats.finishing=Math.min(99,career.stats.finishing+1)}}else match.red++;match.goalFlash=1.2;cameraShake=.55;toast(team==='blue'?'GOAL! DEVOUR THE MOMENT.':'THE OPPONENT SCORES. RESET.');ball.owner=null;ball.velocity.set(0,0,0);ball.position.set(0,.5,0);for(const p of players){p.root.position.copy(p.home);p.velocity.set(0,0,0)}user.root.position.set(0,0,-8);ball.position.set(0,.5,0);setHud()}
function nearestPlayer(team,pos,includeKeeper=true){let best=null,dist=Infinity;for(const p of teams[team]){if(!includeKeeper&&p.keeper)continue;const d=p.root.position.distanceToSquared(pos);if(d<dist){dist=d;best=p}}return best}
function aimDirection(){const forward=new THREE.Vector3(Math.sin(cameraYaw),0,-Math.cos(cameraYaw));if(Math.abs(moveInput.x)+Math.abs(moveInput.y)>.12){const dir=new THREE.Vector3(moveInput.x,0,-moveInput.y);dir.applyAxisAngle(new THREE.Vector3(0,1,0),cameraYaw);if(dir.lengthSq()>.1)return dir.normalize()}return forward.normalize()}
function doShoot(){if(!match.active||match.paused)return;let shooter=ball.owner;if(!shooter&&selectedPlayer&&selectedPlayer.root.position.distanceTo(ball.position)<2.2){shooter=selectedPlayer;ball.owner=shooter}if(!shooter){toast('GET TO THE BALL');return}if(shooter!==user){selectedPlayer=user;toast('SWITCHED TO EGOIST');return}const dir=aimDirection();if(Math.abs(moveInput.x)+Math.abs(moveInput.y)<.12){const goalZ=-48;dir.set(-shooter.root.position.x*.012,0,shooter.root.position.z<0?-1:1);if(shooter.root.position.z>0)dir.z=-1;dir.normalize()}const dist=Math.abs(shooter.root.position.z);let power=shooter.weapon==='Power Shot'?33:shooter.weapon==='Curve Shot'?29:25;let accuracy=Math.max(.15,1-dist/100);if(shooter.weapon==='Predator Eye')accuracy=Math.min(1,accuracy+.22);dir.x+=(Math.random()-.5)*(1-accuracy)*.42;dir.normalize();ball.owner=null;ball.position.copy(shooter.root.position).add(new THREE.Vector3(0,.55,0)).addScaledVector(dir,.9);ball.velocity.copy(dir).multiplyScalar(power);ball.velocity.y=shooter.weapon==='Power Shot'?6:4.2;if(flowTimer>0){ball.velocity.multiplyScalar(1.22);ball.velocity.y+=1}ball.spin=shooter.weapon==='Curve Shot'?.7:0;shooter.stamina=Math.max(0,shooter.stamina-3);career.flowPoints=Math.min(100,career.flowPoints+13);shooter.root.rotation.y=Math.atan2(-dir.x,-dir.z);toast(shooter.weapon.toUpperCase()+'!')}
function doPass(){if(!match.active||match.paused)return;let passer=ball.owner||selectedPlayer;if(ball.owner!==user&&selectedPlayer!==user){selectedPlayer=user;toast('SWITCHED TO EGOIST');return}if(!ball.owner&&passer.root.position.distanceTo(ball.position)>2.2){toast('GET TO THE BALL');return}const mate=teams.blue.filter(p=>p!==passer&&!p.keeper).sort((a,b)=>a.root.position.distanceToSquared(passer.root.position)-b.root.position.distanceToSquared(passer.root.position))[0];if(!mate)return;const dir=mate.root.position.clone().sub(passer.root.position).setY(0).normalize();ball.owner=null;ball.position.copy(passer.root.position).add(new THREE.Vector3(0,.5,0)).addScaledVector(dir,.85);ball.velocity.copy(dir).multiplyScalar(15);ball.velocity.y=1.3;selectedPlayer=user;career.flowPoints=Math.min(100,career.flowPoints+6);toast(`PASS → ${mate.name.toUpperCase()}`)}
function doDribble(){if(!match.active||match.paused)return;if(ball.owner!==user){if(selectedPlayer!==user){selectedPlayer=user;toast('EGOIST SELECTED');return}if(selectedPlayer.root.position.distanceTo(ball.position)<2.2)ball.owner=user;else{toast('GET TO THE BALL');return}}const dir=aimDirection();const weaponBoost=user.weapon==='Dribbling'?1.5:1;ball.owner=null;ball.position.copy(user.root.position).add(new THREE.Vector3(0,.4,0)).addScaledVector(dir,1.1);ball.velocity.copy(dir).multiplyScalar((8+(sprintHeld?4:0))*weaponBoost);ball.velocity.y=1;career.flowPoints=Math.min(100,career.flowPoints+5);toast('BURST DRIBBLE')}
function activateFlow(){if(!match.active||match.paused)return;if(flowTimer>0){toast('FLOW IS ACTIVE');return}if(career.flowPoints<100){toast('FLOW NEEDS 100%');return}career.flowPoints=0;flowTimer=10;flowTier++;user.flow=true;toast('FLOW STATE: DEVOUR THE FIELD')}
function switchPlayer(){const next=nearestPlayer('blue',ball.position,false);if(next){selectedPlayer=next;toast(`CONTROL: ${next.name.toUpperCase()}`)}}
function action(action){if(action==='shoot')doShoot();if(action==='pass')doPass();if(action==='dribble')doDribble();if(action==='flow')activateFlow();if(action==='switch')switchPlayer();if(action==='sprint')sprintHeld=true}
window.addEventListener('keydown',e=>{keys.add(e.key.toLowerCase());if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.repeat)return;if(e.code==='Space')doShoot();if(e.key.toLowerCase()==='e')doPass();if(e.key.toLowerCase()==='q')doDribble();if(e.key.toLowerCase()==='f')activateFlow();if(e.key.toLowerCase()==='r')switchPlayer();if(e.key==='Escape'&&match.active)togglePause()});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
