const joy=$('#joystick'),knob=$('#joy-knob');joy.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;const r=joy.getBoundingClientRect();joyOrigin={x:r.left+r.width/2,y:r.top+r.height/2};joy.setPointerCapture(e.pointerId);updateJoy(e)});joy.addEventListener('pointermove',e=>{if(joyPointer===e.pointerId)updateJoy(e)});function updateJoy(e){const dx=e.clientX-joyOrigin.x,dy=e.clientY-joyOrigin.y,len=Math.hypot(dx,dy),max=32,scale=Math.min(1,max/(len||1));moveInput.set(dx*scale/max,-dy*scale/max);knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`}joy.addEventListener('pointerup',e=>{if(joyPointer===e.pointerId){joyPointer=null;moveInput.set(0,0);knob.style.transform='translate(0,0)'}});joy.addEventListener('pointercancel',()=>{joyPointer=null;moveInput.set(0,0);knob.style.transform='translate(0,0)'});
function togglePause(){if(!match.active)return;match.paused=!match.paused;if(match.paused){mountModal(`<div class="modal"><div class="modal-kicker">MATCH CONTROL // PAUSED</div><h2>TAKE A BREATH.</h2><p>The field is waiting. Re-enter and make your next move count.</p><div class="modal-actions"><button class="primary-cta" id="resume-game"><span>RESUME MATCH</span><b>↗</b></button><button class="secondary-button" id="quit-game">END MATCH</button></div></div>`);$('#resume-game').onclick=()=>{closeModal();match.paused=false};$('#quit-game').onclick=()=>{closeModal();finishMatch()}}else closeModal()}
