function clampPlayer(p){p.root.position.x=THREE.MathUtils.clamp(p.root.position.x,-30,30);p.root.position.z=THREE.MathUtils.clamp(p.root.position.z,-49,49)}
function moveToward(p,target,speed,dt){p.target.copy(target);const delta=target.clone().sub(p.root.position);delta.y=0;if(delta.length()>.12){const dir=delta.normalize();p.velocity.x=THREE.MathUtils.damp(p.velocity.x,dir.x*speed,7,dt);p.velocity.z=THREE.MathUtils.damp(p.velocity.z,dir.z*speed,7,dt);p.root.rotation.y=Math.atan2(-dir.x,-dir.z)}else{p.velocity.x=THREE.MathUtils.damp(p.velocity.x,0,9,dt);p.velocity.z=THREE.MathUtils.damp(p.velocity.z,0,9,dt)}p.root.position.x+=p.velocity.x*dt;p.root.position.z+=p.velocity.z*dt;clampPlayer(p)}
function aiUpdate(dt){const carrier=ball.owner;for(const p of players){if(p===user)continue;let target=p.home.clone(),speed=p.speed*(aiDifficulty==='ELITE'?1.13:aiDifficulty==='ROOKIE'?.85:1);if(carrier){if(p.team!==carrier.team){const chaser=nearestPlayer(p.team,carrier.root.position,false);if(chaser===p){target.copy(carrier.root.position);speed*=1.08}else{target.add(carrier.root.position.clone().sub(new THREE.Vector3(0,0,p.team==='red'?-9:9)).multiplyScalar(.16))}}else{target.z+=(p.team==='blue'?-1:1)*6;if(p.index%3===0)target.x+=Math.sin(match.elapsed*.65+p.index)*4}}else{if(p.team==='blue')target.z-=Math.max(0,-ball.position.z+10)*.24;else target.z+=Math.max(0,ball.position.z-10)*.24;const nearest=nearestPlayer(p.team,ball.position,false);if(nearest===p)target.lerp(ball.position,.62)}if(p.keeper){target.x=THREE.MathUtils.clamp(ball.position.x,-5.5,5.5);target.z=p.team==='blue'?-44:44;speed*=.75}moveToward(p,target,speed,dt)}
 if(!carrier){for(const p of players){if(p.keeper)continue;const d=p.root.position.distanceTo(ball.position);if(d<1.05&&ball.position.y<1.5&&ball.velocity.length()<17){ball.owner=p;ball.velocity.set(0,0,0);if(p.team==='blue'&&p!==user){selectedPlayer=p;toast(`${p.name.toUpperCase()} ON THE BALL`) }break}}}else if(carrier.team==='red'){const goalDir=new THREE.Vector3(0,0,1);const keeper=teams.blue[10];if(carrier.root.position.distanceTo(keeper.root.position)<1.65){ball.owner=null;ball.velocity.set((Math.random()-.5)*8,3,-12);toast('GOALKEEPER BLOCK!')}}}
function updateBall(dt){if(ball.owner){const p=ball.owner;const dir=new THREE.Vector3(0,0,-1).applyAxisAngle(new THREE.Vector3(0,1,0),p.root.rotation.y);const offset=dir.multiplyScalar(p===user?1.05:.95);ball.position.set(p.root.position.x+offset.x,.48+Math.abs(Math.sin(match.elapsed*10))*.16,p.root.position.z+offset.z);ball.velocity.set(0,0,0)}else{ball.velocity.y-=19*dt;ball.position.addScaledVector(ball.velocity,dt);if(ball.position.y<.48){ball.position.y=.48;if(ball.velocity.y< -1.5)ball.velocity.y*=-.42;else ball.velocity.y=0;ball.velocity.x*=.98;ball.velocity.z*=.98}if(ball.spin){ball.velocity.x+=ball.spin*dt;ball.spin*=.99}if(ball.position.x<-34||ball.position.x>34)ball.velocity.x*=-.65;if(ball.position.z<-53||ball.position.z>53){if(Math.abs(ball.position.x)<3.9&&ball.position.y<3.4){resetAfterGoal(ball.position.z<0?'blue':'red');return}ball.velocity.z*=-.6;ball.position.z=THREE.MathUtils.clamp(ball.position.z,-52,52)}if(ball.velocity.length()<.32&&ball.position.y<=.5)ball.velocity.set(0,0,0)}ballGroup.position.copy(ball.position);ballGroup.rotation.x+=ball.velocity.z*dt;ballGroup.rotation.z-=ball.velocity.x*dt;ballShadow.position.set(ball.position.x,.012,ball.position.z);ballShadow.scale.setScalar(THREE.MathUtils.clamp(1.2-ball.position.y*.24,.45,1))}
