 function openWeapons(){const weapons=[['Direct Shot','Fast first-time finish','STARTER'],['Spatial Awareness','Reveal runs and passing lanes','STARTER'],['Predator Eye','Precision from shooting angles','LV. 2'],['Dribbling','Burst through close pressure','LV. 2'],['Speed','Explosive acceleration','LV. 3'],['Power Shot','High velocity, lower accuracy','LV. 3'],['Curve Shot','Bend shots around defenders','LV. 4'],['Trapping','Magnetic first touch','LV. 4']];mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">WEAPON LOADOUT // 1 PRIMARY + 2 SECONDARY</div><h2>CHOOSE YOUR EDGE</h2><p>Weapons unlock through match growth. Your active primary changes shot, dribble and movement behavior.</p><div class="weapon-list">${weapons.map(([w,d,l])=>{const open=career.unlocked.includes(w)||career.level>=(+l.replace('LV. ','')||1);return `<div class="weapon-row"><div><b>${w}</b><small>${d} · ${open?'UNLOCKED':l+' REQUIRED'}</small></div><button data-equip="${w}" ${open?'':'disabled'}>${career.weapon===w?'EQUIPPED':career.secondaries.includes(w)?'SECONDARY':'EQUIP'}</button></div>`}).join('')}</div></div>`);$('#modal-root').querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const w=b.dataset.equip;if(b.disabled)return;if(career.weapon===w)return;if(career.unlocked.includes(w))career.weapon=w;else if(career.secondaries.includes(w))career.secondaries=career.secondaries.filter(x=>x!==w);else if(career.secondaries.length<2)career.secondaries.push(w);else{career.secondaries.shift();career.secondaries.push(w)}user.weapon=career.weapon;saveCareer();refreshProfile();openWeapons()})}
 function openSettings(){mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">SYSTEM CONFIGURATION</div><h2>SETTINGS</h2><p>Adjust the match simulation for your device and preferred challenge.</p><div class="form-grid"><div class="form-field"><label>AI DIFFICULTY</label><select id="setting-difficulty"><option>ROOKIE</option><option>STRIKER</option><option>ELITE</option></select></div><div class="form-field"><label>CAMERA SENSITIVITY</label><select id="setting-camera"><option>LOW</option><option>STANDARD</option><option>HIGH</option></select></div><div class="form-field"><label>AUDIO</label><select id="setting-audio"><option>ON</option><option>OFF</option></select></div></div><div class="modal-actions"><button class="primary-cta" id="settings-done"><span>DONE</span><b>✓</b></button></div></div>`);$('#setting-difficulty').value=career.difficulty||'STRIKER';$('#setting-camera').value=career.camera||'STANDARD';$('#setting-audio').value=career.audio||'ON';$('#settings-done').onclick=()=>{career.difficulty=$('#setting-difficulty').value;career.camera=$('#setting-camera').value;career.audio=$('#setting-audio').value;aiDifficulty=career.difficulty;saveCareer();closeModal()}}
 function openTraining(){mountModal(`<div class="modal"><button class="modal-close" data-close>×</button><div class="modal-kicker">TRAINING FACILITY // DAILY EGO TEST</div><h2>BUILD YOUR WEAPON</h2><p>Choose a drill. Complete it on the pitch by scoring or completing successful actions before time expires.</p><div class="selection-grid"><button class="selection-card selected" data-drill="finishing"><b>01 / FINISHING</b><small>SHOOTING · +XP ON GOALS</small></button><button class="selection-card" data-drill="dribble"><b>02 / DRIBBLE COURSE</b><small>BEAT DEFENDERS · +CONTROL</small></button><button class="selection-card" data-drill="passing"><b>03 / PASSING GRID</b><small>FIND A TEAMMATE · +VISION</small></button><button class="selection-card" data-drill="survival"><b>04 / SURVIVAL MATCH</b><small>RISING PRESSURE · BONUS XP</small></button></div><div class="modal-actions"><button class="primary-cta" id="begin-drill"><span>START DRILL</span><b>↗</b></button></div></div>`);let drill='finishing';$('#modal-root').querySelectorAll('[data-drill]').forEach(b=>b.onclick=()=>{$$('#modal-root [data-drill]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');drill=b.dataset.drill});$('#begin-drill').onclick=()=>startMatch(drill==='survival'?'survival':'training',drill)}
 function setHud(){const secs=Math.max(0,Math.ceil(match.duration-match.elapsed));$('#match-clock').textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;$('#score-blue').textContent=match.blue;$('#score-red').textContent=match.red;$('#stamina-readout').textContent=Math.round(user.stamina);$('#stamina-fill').style.width=`${user.stamina}%`;$('#flow-readout').textContent=`${Math.round(career.flowPoints)}%`;$('#flow-meter-fill').style.width=`${career.flowPoints}%`;$('#flow-hint').textContent=flowTimer>0?'FLOW ACTIVE — DEVOUR THE FIELD':career.flowPoints>=100?'FLOW READY — PRESS F':'MAKE YOUR MOVE'}
-function startMatch(mode='career',drill='finishing'){closeModal();match={active:true,paused:false,elapsed:0,duration:mode==='training'?75:120,blue:0,red:0,mode,drill,goalFlash:0};ball.owner=null;ball.velocity.set(0,0,0);ball.position.set(0,.5,0);ballGroup.position.copy(ball.position);user.stamina=100;career.flowPoints=0;flowTimer=0;selectedPlayer=user;for(const p of players){const f=p.home;p.root.position.copy(f);p.velocity.set(0,0,0)}user.root.position.set(0,0,-8);user.home.copy(user.root.position);$('#game-mode-label').textContent=mode==='career'?'CAREER MATCH':mode==='practice'?'QUICK MATCH':mode==='survival'?'SURVIVAL MATCH':`${drill.toUpperCase()} DRILL`;$('#home-screen').classList.add('hidden');$('#game-screen').classList.remove('hidden');$('#touch-controls').classList.add('active');$('#touch-controls').style.pointerEvents='auto';$('#modal-root').innerHTML='';setHud();toast('FIRST TO THE BALL. MAKE YOUR EGO COUNT.')}
+function startMatch(mode='career',drill='finishing'){closeModal();match={active:true,paused:false,elapsed:0,duration:mode==='training'?75:120,blue:0,red:0,mode,drill,goalFlash:0};ball.owner=null;ball.velocity.set(0,0,0);ball.position.set(0,.5,0);ballGroup.position.copy(ball.position);user.stamina=100;career.flowPoints=0;flowTimer=0;selectedPlayer=user;for(const p of players){const f=p.home;p.root.position.copy(f);p.velocity.set(0,0,0)}user.root.position.set(0,0,-8);user.home.copy(user.root.position);$('#game-mode-label').textContent=mode==='career'?'CAREER MATCH':mode==='practice'?'QUICK MATCH':mode==='survival'?'SURVIVAL MATCH':`${drill.toUpperCase()} DRILL`;$('#home-screen').classList.add('hidden');$('#game-screen').classList.remove('hidden');$('#touch-controls').classList.add('active');$('#modal-root').innerHTML='';setHud();toast('FIRST TO THE BALL. MAKE YOUR EGO COUNT.')}
 function finishMatch(){match.active=false;match.paused=false;ball.owner=null;const won=match.blue>match.red;const earned=20+match.blue*35+(won?30:0)+(match.mode==='training'?12:0);career.xp+=earned;career.matches++;career.record+=won?1:0;career.rating=Math.min(99,career.rating+(won?2:1)+Math.min(match.blue,2));career.rank=rankFromRating(career.rating);career.flowPoints=Math.min(100,career.flowPoints);while(career.xp>=career.level*100){career.xp-=career.level*100;career.level++;career.rating=Math.min(99,career.rating+2);career.unlocked=['Direct Shot','Spatial Awareness',...(career.level>=2?['Predator Eye','Dribbling']:[]),...(career.level>=3?['Speed','Power Shot']:[]),...(career.level>=4?['Curve Shot','Trapping']:[])];}saveCareer();refreshProfile();setHud();mountModal(`<div class="modal result-modal"><div class="modal-kicker">${won?'EGOIST VICTORY':'SELECTION COMPLETE'} // MATCH ${career.matches}</div><h2>${won?'YOU SURVIVED.':'THE PROJECT CONTINUES.'}</h2><p>Final score <strong>${match.blue} — ${match.red}</strong>. You earned <strong>+${earned} XP</strong>${match.mode==='training'?' for your training effort':''}.</p><div class="stat-row"><span>STRIKER RATING</span><b>${career.rating} · ${career.rank}</b></div><div class="stat-row"><span>CAREER RECORD</span><b>${career.record} W / ${career.matches-career.record} L</b></div><div class="modal-actions"><button class="primary-cta" id="result-home"><span>RETURN TO PROJECT</span><b>↗</b></button><button class="secondary-button" id="result-rematch">REMATCH</button></div></div>`);$('#result-home').onclick=()=>{closeModal();$('#game-screen').classList.add('hidden');$('#home-screen').classList.remove('hidden');$('#touch-controls').classList.remove('active')};$('#result-rematch').onclick=()=>startMatch(match.mode,match.drill)}
 function resetAfterGoal(team){if(team==='blue'){match.blue++;if(ball.owner===user){career.goals++;career.stats.finishing=Math.min(99,career.stats.finishing+1)}}else match.red++;match.goalFlash=1.2;cameraShake=.55;toast(team==='blue'?'GOAL! DEVOUR THE MOMENT.':'THE OPPONENT SCORES. RESET.');ball.owner=null;ball.velocity.set(0,0,0);ball.position.set(0,.5,0);for(const p of players){p.root.position.copy(p.home);p.velocity.set(0,0,0)}user.root.position.set(0,0,-8);ball.position.set(0,.5,0);setHud()}
 function nearestPlayer(team,pos,includeKeeper=true){let best=null,dist=Infinity;for(const p of teams[team]){if(!includeKeeper&&p.keeper)continue;const d=p.root.position.distanceToSquared(pos);if(d<dist){dist=d;best=p}}return best}
 function aimDirection(){const forward=new THREE.Vector3(Math.sin(cameraYaw),0,-Math.cos(cameraYaw));if(Math.abs(moveInput.x)+Math.abs(moveInput.y)>.12){const dir=new THREE.Vector3(moveInput.x,0,-moveInput.y);dir.applyAxisAngle(new THREE.Vector3(0,1,0),cameraYaw);if(dir.lengthSq()>.1)return dir.normalize()}return forward.normalize()}

